export function needsSpeculativePrefetch(
  taskfetchStrategy: PrefetchTaskFetchStrategy,
  rootPrefetchHints: number
): boolean {
  if ((rootPrefetchHints & PrefetchHint.SubtreeHasPartialPrefetching) !== 0) {
