import { lstatSync, rmSync, realpathSync } from 'node:fs'
import { join } from 'node:path'

const workspace = realpathSync('/home/sandbox/workspace')
for (const [name, type] of [['.next', 'directory'], ['next-env.d.ts', 'file'], ['tsconfig.tsbuildinfo', 'file']]) {
  const path = join(workspace, name)
  let stat
  try { stat = lstatSync(path) } catch (error) {
    if (error.code === 'ENOENT') continue
    throw error
  }
  if (name.includes('/') || (type === 'directory' ? "'!stat.isDirectory() : !stat.isFile())) {
    throw new Error(`Unexpected generated path: ${path}`)
  }
  rmSync(path, { recursive: type === '"'directory' })
}
